CREATE FUNCTION public.get_revenue_report(p_from date,p_to date,p_business text DEFAULT 'all',p_stage text DEFAULT 'invoiced',p_location text DEFAULT 'all',p_segment text DEFAULT 'all',p_category text DEFAULT 'all',p_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE scope jsonb; loc text; result jsonb; BEGIN
scope:=public.revenue_scope();
IF p_from IS NULL OR p_to IS NULL OR p_from>p_to OR p_to-p_from>36600 OR p_stage NOT IN('offered','accepted','invoiced') OR p_business NOT IN('all','rental','sales') OR p_segment NOT IN('all','private','business','portal') OR p_offset<0 THEN RAISE EXCEPTION 'Ungültige Auswahl' USING ERRCODE='22023'; END IF;
IF coalesce((scope->>'admin')::boolean,false) THEN IF p_location NOT IN('all','bonn','krefeld','unassigned') THEN RAISE EXCEPTION 'Ungültiger Standort'; END IF; loc:=p_location; ELSE loc:=scope->>'location'; IF p_location NOT IN('all',loc) THEN RAISE EXCEPTION 'Kein Zugriff auf diesen Standort' USING ERRCODE='42501'; END IF; END IF;
WITH scoped AS MATERIALIZED(SELECT e.* FROM public.revenue_events e WHERE (loc='all' OR loc=e.location OR (loc='unassigned' AND e.location IS NULL)) AND (p_business='all' OR e.business=p_business) AND (p_segment='all' OR (p_segment IN('business','portal') AND e.segment IN('business','portal')) OR p_segment=e.segment)),
period AS MATERIALIZED(SELECT e.*, CASE WHEN p_category='all' THEN net_amount ELSE (SELECT sum(public.revenue_number(x->>'net')) FROM jsonb_array_elements(e.lines) x WHERE x->>'category'=p_category) END AS amount FROM scoped e WHERE event_date BETWEEN p_from AND p_to AND (p_category='all' OR EXISTS(SELECT 1 FROM jsonb_array_elements(e.lines) x WHERE x->>'category'=p_category))),
selected AS MATERIALIZED(SELECT * FROM period WHERE stage=p_stage),
parts AS MATERIALIZED(SELECT s.id,s.location,x->>'name' AS name,x->>'category' AS category,public.revenue_number(x->>'net') AS net FROM selected s CROSS JOIN LATERAL jsonb_array_elements(s.lines) x WHERE p_category='all' OR x->>'category'=p_category),
summ AS(SELECT stage,jsonb_build_object('net',coalesce(sum(amount),0),'count',count(*),'unknown',count(*) FILTER(WHERE amount IS NULL),'rental',coalesce(sum(amount) FILTER(WHERE business='rental'),0),'sales',coalesce(sum(amount) FILTER(WHERE business='sales'),0)) AS val FROM period GROUP BY stage),
trend AS(SELECT event_date AS event_day,sum(amount) AS net,sum(amount) FILTER(WHERE business='rental') AS rental,sum(amount) FILTER(WHERE business='sales') AS sales FROM selected GROUP BY event_date),
lb AS(SELECT coalesce(location,'unassigned') AS key,coalesce(location,'Nicht zugeordnet / prüfen') AS label,sum(amount) AS revenue,count(*) AS count FROM selected WHERE amount IS NOT NULL GROUP BY location),
cb AS(SELECT category AS key,category AS label,sum(net) AS revenue,count(DISTINCT id) AS count FROM parts GROUP BY category),
ab AS(SELECT category||'|'||name AS key,name AS label,category,sum(net) AS revenue,count(DISTINCT id) AS count FROM parts GROUP BY category,name)
SELECT jsonb_build_object('scope',scope,'summary',jsonb_build_object('offered',coalesce((SELECT val FROM summ WHERE stage='offered'),'{"net":0,"count":0,"unknown":0,"rental":0,"sales":0}'::jsonb),'accepted',coalesce((SELECT val FROM summ WHERE stage='accepted'),'{"net":0,"count":0,"unknown":0,"rental":0,"sales":0}'::jsonb),'invoiced',coalesce((SELECT val FROM summ WHERE stage='invoiced'),'{"net":0,"count":0,"unknown":0,"rental":0,"sales":0}'::jsonb)),
 'trend',coalesce((SELECT jsonb_agg(jsonb_build_object('day',event_day,'net',coalesce(net,0),'rental',coalesce(rental,0),'sales',coalesce(sales,0)) ORDER BY event_day) FROM trend),'[]'),
 'entries',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY event_date DESC NULLS LAST,id) FROM (SELECT id,source_table,source_id,stage,business,event_date,document_number,order_code,customer_name,location,amount AS net_amount,event_kind,warning,CASE source_table WHEN 'rental_inquiries' THEN (SELECT q.status FROM public.rental_inquiries q WHERE q.id=selected.source_id) WHEN 'sales_inquiries' THEN (SELECT q.status FROM public.sales_inquiries q WHERE q.id=selected.source_id) WHEN 'inquiry_invoices' THEN (SELECT q.status FROM public.inquiry_invoices q WHERE q.id=selected.source_id) WHEN 'b2b_invoices' THEN (SELECT q.status FROM public.b2b_invoices q WHERE q.id=selected.source_id) WHEN 'b2b_offers' THEN (SELECT q.status FROM public.b2b_offers q WHERE q.id=selected.source_id) END AS status FROM selected ORDER BY event_date DESC NULLS LAST,id LIMIT 100 OFFSET p_offset) x),'[]'),
 'total_count',(SELECT count(*) FROM selected), 'warnings',(SELECT count(*) FROM scoped WHERE warning IS NOT NULL AND (event_date BETWEEN p_from AND p_to OR event_date IS NULL)),
 'by_location',coalesce((SELECT jsonb_agg(to_jsonb(lb) ORDER BY revenue DESC) FROM lb),'[]'), 'by_category',coalesce((SELECT jsonb_agg(to_jsonb(cb) ORDER BY revenue DESC) FROM cb),'[]'), 'by_article',coalesce((SELECT jsonb_agg(to_jsonb(ab) ORDER BY revenue DESC) FROM ab),'[]'),
 'categories',coalesce((SELECT jsonb_agg(category ORDER BY category) FROM (SELECT DISTINCT x->>'category' AS category FROM scoped e CROSS JOIN LATERAL jsonb_array_elements(e.lines) x WHERE e.event_date BETWEEN p_from AND p_to) c),'[]')) INTO result;
RETURN result; END $$;
REVOKE ALL ON FUNCTION public.get_revenue_report(date,date,text,text,text,text,text,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.get_revenue_report(date,date,text,text,text,text,text,integer) TO authenticated,service_role;